function ActivityPtUtils.IsUnlockQuest(id)
    local vo = ActivityPtUtils.GetActivityPtPlotVo(id)
    if not vo then
        return false
    end
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local num = ActivityPtComponent:GetGetActivityGoodsNum()
    if checkNumber(num) < checkNumber(vo.unlockPropNum) then
        return false
    end

    return ActivityPtUtils.IsPassQuest(vo.unlockStory)
end

function ActivityPtUtils.IsPassQuest(id)
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local newId = ActivityPtComponent:GetNewQuestId()
    return checkNumber(newId) >= checkNumber(id)
end

function ActivityPtUtils.GetNewQuestId()
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local newId = ActivityPtComponent:GetNewQuestId()
    return newId
end

function ActivityPtUtils.GetFinishDayTask()
    local count = 0
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local t = ActivityPtComponent:GetDailyTask()
    for k, v in pairs(t) do
        if checkNumber(v.status) == 2 then
            count = count + 1
        end
    end
    return count, table.count(t)
end

function ActivityPtUtils.GetFinishPlanTask()
    local count = 0
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local t = ActivityPtComponent:GetPlanTask()
    for k, v in pairs(t) do
        if checkNumber(v.status) == 2 then
            count = count + 1
        end
    end
    return count, table.count(t)
end

function ActivityPtUtils.GetTaskData(id, type)
    local t = {}
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    if type == 1 then
        t = ActivityPtComponent:GetDailyTask()
    else
        t = ActivityPtComponent:GetPlanTask()
    end

    if not t then
        return nil
    end

    return t[checkString(id)] 
end

--该类型是否有奖励可以领取
function ActivityPtUtils.IsTypeHasCanDrawReward(type)
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local t = {}
    if type == 1 then
        t = ActivityPtComponent:GetDailyTask()
    else
        t = ActivityPtComponent:GetPlanTask()
    end 
    for k, v in pairs(t) do
        if checkNumber(v.status) == 1 then
            return true
        end
    end
    return false
end

function ActivityPtUtils.IsHasCanDrawReward()
    if ActivityPtUtils.IsTypeHasCanDrawReward(1) then
        return true
    end
    return ActivityPtUtils.IsTypeHasCanDrawReward(2)
end

function ActivityPtUtils.IsTaskCanDraw(id, type)
    local data = ActivityPtUtils.GetTaskData(id, type)
    if not data then
        return false
    end

    return (checkNumber(data.status) == 1)
end

function ActivityPtUtils.IsTaskDraw(id, type)
    local data = ActivityPtUtils.GetTaskData(id, type)
    if not data then
        return false
    end

    return (checkNumber(data.status) == 2)
end

--所有的剧情
function ActivityPtUtils.GetAllPlotIds(id)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting4121, id)
    return t
end

--片头动画
function ActivityPtUtils.GetFirstPlotId(id)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting4121, id)
    for k, v in pairs(t) do
        local vo = ActivityPtUtils.GetActivityPtPlotVo(v)
        if checkNumber(vo.firstStory) == 1 then
            return vo
        end
    end
    return nil
end

