end

function ActivityPtUtils.GetActivityData(uuid)
    local ActivityMgr = import('Game.Activity.ActivityMgr')
    local ActivityConstants = import("Game.Activity.ActivityConstants")

    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.ActivityPT and checkInt(v.id) == checkInt(uuid) then
            return v
        end
    end

    return nil
end


return ActivityPtUtils
